export type LogLevel = 'debug' | 'info' | 'warn' | 'error'

export interface Config {
  port: number
  databaseUrl: string
  logLevel: LogLevel
  enableMetrics: boolean
  /** Origins allowed to call the billing API from a browser (CORS). */
  allowedOrigins: string[]
  requestTimeoutMs: number
}

/** The variables this service reads. Anything else in the environment is ignored. */
const ENV_NAMES = [
  'PORT',
  'DATABASE_URL',
  'LOG_LEVEL',
  'ENABLE_METRICS',
  'ALLOWED_ORIGINS',
  'REQUEST_TIMEOUT_MS',
] as const

type EnvName = (typeof ENV_NAMES)[number]

/** Shown next to each variable name in the startup error. Never includes the value. */
const HINTS: Record<EnvName, string> = {
  PORT: 'must be an integer from 1 to 65535',
  DATABASE_URL: 'must be a postgres:// or postgresql:// URL',
  LOG_LEVEL: 'must be one of debug, info, warn, error',
  ENABLE_METRICS: 'must be one of true, false, 1, 0, yes, no',
  ALLO
… [truncated] …
ervice configuration from the environment.
 * Empty strings count as unset. Throws one Error naming every invalid variable.
 */
export function loadConfig(env: Record<string, string | undefined> = process.env): Config {
  const raw: Record<string, string | undefined> = {}
  for (const name of ENV_NAMES) {
    const value = env[name]
    raw[name] = value === '' ? undefined : value
  }

  const result = schema.safeParse(raw)
  if (!result.success) {
    const invalid = new Set(result.error.issues.map((issue) => String(issue.path[0])))
    const lines = ENV_NAMES.filter((name) => invalid.has(name)).map(
      (name) => `  ${name} ${HINTS[name]}`,
    )
    throw new Error(`Invalid configuration:\n${lines.join('\n')}`)
  }

  const data = result.data
  return {
    port: data.PORT,
    databaseUrl: data.DATABASE_URL,
    logLevel: data.LOG_LEVEL,
    enableMetrics: data.ENABLE_METRICS,
    allowedOrigins: data.ALLOWED_ORIGINS,
    requestTimeoutMs: data.REQUEST_TIMEOUT_MS,
  }
}

